/**
 * A landing page that reads as the org's own app: a hero in the brand's display font with its
 * mark, a headline metric and a short set of entrances. The theme (theme.ts) carries the font,
 * density, motion, elevation and chart colour; the logo files are static imports, so they are
 * inlined into the bundle. Nothing here writes data.
 */
import { createRoot } from 'react-dom/client';
import {
  BrandMark,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  EmptyState,
  Hero,
  Icon,
  Reveal,
  Skeleton,
  SurfaceApp,
  useMetric,
} from '@cynap/surface-sdk';

import logo from './logo.png';
import logoDark from './logo-dark.png';
import { theme } from './theme';
import './styles.css';

/** The org's display name, one governed metric the hero shows, and how a reader names it. Replace all three. */
const ORG_NAME = 'REPLACE_WITH_ORG_NAME';
const HEADLINE_METRIC = 'REPLACE_WITH_HEADLINE_METRIC';
const HEADLINE_LABEL = 'REPLACE_WITH_HEADLINE_LABEL';

type Row = Record<string, unknown>;
const valueOf = (row: Row) => (typeof row.value === 'number' ? row.value : Number(row.value) || 0);

/** `<Icon>` takes a literal name, so each highlight carries its drawn icon. */
const HIGHLIGHTS = [
  { icon: <Icon name="sparkles" />, title: 'Always current', body: 'Every number is read live from your own records.' },
  { icon: <Icon name="shield-check" />, title: 'Governed', body: 'Each figure comes from one named metric definition.' },
  { icon: <Icon name="trending-up" />, title: 'At a glance', body: 'The headline first, the detail one click away.' },
];

function Landing() {
  const headline = useMetric(HEADLINE_METRIC);
  const rows = [...(headline.data?.rows ?? [])] as Row[];
  const total = rows.reduce((sum, row) => sum + valueOf(row), 0);

  return (
    <Hero
      mark={<BrandMark src={logo} darkSrc={logoDark} alt={ORG_NAME} size="lg" />}
      eyebrow={ORG_NAME}
      title="Your operations, in one place"
      description="A live view of the work that matters, in your own colours and type."
    >
      <div className="tpl-grid">
        <Reveal>
          <Card>
            <CardHeader>
              <CardTitle>Headline</CardTitle>
              <CardDescription>{HEADLINE_LABEL}</CardDescription>
            </CardHeader>
            <CardContent>
              {headline.state === 'loading' ? (
                <Skeleton height={48} />
              ) : rows.length === 0 ? (
                <EmptyState title="No data yet" />
              ) : (
                <p className="tpl-figure">{total.toLocaleString()}</p>
              )}
            </CardContent>
          </Card>
        </Reveal>
        {HIGHLIGHTS.map((item, index) => (
          <Reveal key={item.title} delay={(index + 1) * 60}>
            <Card>
              <CardHeader>
                {item.icon}
                <CardTitle>{item.title}</CardTitle>
                <CardDescription>{item.body}</CardDescription>
              </CardHeader>
            </Card>
          </Reveal>
        ))}
      </div>
    </Hero>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'brand-portal', version: '1.0.0' }} theme={theme}>
      <Landing />
    </SurfaceApp>
  );
}

