/**
 * The brand: the one file allowed to hold colour literals. Replace the values with the brand's.
 * `fonts.display` is a static import of a file in this surface (add brand-display.woff2 beside
 * this file); the SDK registers it and names its family, and `Hero` headlines use it.
 */
import { defineSurfaceTheme } from '@cynap/surface-sdk';

import brandDisplay from './brand-display.woff2';

export const theme = defineSurfaceTheme({
  fonts: { display: brandDisplay },
  density: 'spacious',
  motion: 'expressive',
  light: {
    '--color-background-primary': '#fbfaf7',
    '--color-text-primary': '#1d1a16',
    '--color-ring-primary': '#c2410c',
    '--border-radius-lg': '16px',
    '--border-radius-xl': '24px',
    '--shadow-md': '0 1px 2px rgb(29, 26, 22, 0.06), 0 8px 24px rgb(29, 26, 22, 0.08)',
    '--font-weight-semibold': '700',
    '--chart-1': '#c2410c',
  },
  dark: {
    '--color-background-primary': '#14110e',
    '--color-text-primary': '#f4efe8',
    '--color-ring-primary': '#fb923c',
    '--border-radius-lg': '16px',
    '--border-radius-xl': '24px',
    '--shadow-md': '0 1px 2px rgb(0, 0, 0, 0.4), 0 8px 24px rgb(0, 0, 0, 0.5)',
    '--font-weight-semibold': '700',
    '--chart-1': '#fb923c',
  },
});

